self.KB_CONTENT["card:780877"]={"id":"card:780877","ty":"card","sourceId":"780877","title":"『現金流量表調整沖銷分錄維護作業』中的『公司別 (TZ005)』為何？","ver":"GP4以上","topic":"科目","keywords":["科目","分錄","控管","沖銷"],"y":"other","answer":"* 可選擇1.子公司、2.母公司、3.側流公司。* 當公司別為「3.側流公司」時，「關係人代號」不可空白。* 若公司別為「1.子公司」、「2.母公司」時，則依輸入的會計科目於科目資料建立作業(ACTI03)「關係人管理」的設定作控管。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
