self.KB_CONTENT["card:756405"]={"id":"card:756405","ty":"card","sourceId":"756405","title":"『訂單已交量重計作業』的作業目的為何？","ver":"iGP","topic":"銷貨單","keywords":["銷貨單","銷退單","單身","客戶"],"y":"explain","answer":"屬於資料異常的維護程式。無須定期執行，當發現客戶訂單建立作業單身之「已交數量」資料異常，經核對資料後確實銷貨單及銷退單原始單據資料正確時，可透過本作業重新計算訂單單身之已交量。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
