self.KB_CONTENT["field:757587"]={"id":"field:757587","ty":"field","sourceId":"757587","title":"發票全額銷退時，只產生一筆作廢的發票資料","ver":"iGP","topic":"","keywords":[],"job":"進項憑證產生作業","code":"","answer":"銷項憑證中若有一筆銷貨、且一筆全數銷退，當兩筆資料的發票號碼相同且金額相同時，將只產生一筆作廢的發票資料；反之，則反。","file":"fields.jsonl"};
